do $$ begin create type public.ledger_type as enum ('earning','payout_hold','payout_release','adjustment'); exception when duplicate_object then null; end $$;
create table if not exists public.reward_ledger (id uuid primary key default gen_random_uuid(), creator_id uuid not null references public.profiles(id), submission_id uuid references public.submissions(id), type public.ledger_type not null, amount bigint not null, description text, created_at timestamptz default now());
alter table public.reward_ledger enable row level security;
create policy "creator can read own ledger" on public.reward_ledger for select using (auth.uid() = creator_id);
create or replace function public.credit_submission_reward(p_submission_id uuid,p_approved_views bigint) returns bigint language plpgsql security definer set search_path = public as $$ declare s submissions%rowtype; c campaigns%rowtype; reward bigint; begin select * into s from submissions where id=p_submission_id for update; if not found then raise exception 'submission not found'; end if; select * into c from campaigns where id=s.campaign_id; if not found then raise exception 'campaign not found'; end if; p_approved_views := greatest(0, least(p_approved_views, c.max_views_per_creator)); reward := floor(p_approved_views::numeric / 1000) * c.reward_per_1k; update submissions set status='approved',approved_views=p_approved_views,reward_amount=reward,last_view_check=now() where id=p_submission_id; delete from reward_ledger where submission_id=p_submission_id and type='earning'; insert into reward_ledger(creator_id,submission_id,type,amount,description) values(s.creator_id,s.id,'earning',reward,'Approved campaign views'); update profiles set balance=coalesce(balance,0)+reward where id=s.creator_id; return reward; end; $$;
create or replace function public.request_payout(p_amount bigint,p_method text,p_account_detail text) returns uuid language plpgsql security definer set search_path = public as $$ declare payout_id uuid; bal bigint; begin select balance into bal from profiles where id=auth.uid() for update; if bal is null then raise exception 'profile not found'; end if; if p_amount <= 0 then raise exception 'invalid amount'; end if; if p_amount > bal then raise exception 'insufficient balance'; end if; update profiles set balance=balance-p_amount where id=auth.uid(); insert into payouts(creator_id,amount,method,account_detail,status) values(auth.uid(),p_amount,p_method,p_account_detail,'pending') returning id into payout_id; insert into reward_ledger(creator_id,type,amount,description) values(auth.uid(),'payout_hold',-p_amount,'Payout request'); return payout_id; end; $$;